from rest_framework import viewsets, permissions, status
from rest_framework.decorators import action
from rest_framework.response import Response
from reversion.models import Version
from .models import SalesLead
from .serializers import SalesLeadSerializer

class SalesLeadViewSet(viewsets.ModelViewSet):
    serializer_class = SalesLeadSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return SalesLead.objects.filter(assigned_territory__in=self.request.user.territories.all())

    @action(detail=False, methods=['post'], url_path='restore-deleted')
    def restore_deleted(self, request):
        lead_id = request.data.get('lead_id')
        deleted_versions = Version.objects.get_deleted(SalesLead).filter(object_id=str(lead_id))
        target_version = deleted_versions.first()
        if not target_version:
            return Response({'error': 'Deleted lead not found'}, status=status.HTTP_404_NOT_FOUND)

        # Validate that the snapshot data corresponds to a territory permitted for this rep
        territory_id = target_version.field_dict.get('assigned_territory_id')
        allowed_territory_ids = set(self.request.user.territories.values_list('id', flat=True))
        if territory_id not in allowed_territory_ids:
            return Response({'error': 'Permission denied for this territory lead'}, status=status.HTTP_403_FORBIDDEN)

        target_version.revision.revert()
        restored_lead = SalesLead.objects.get(id=lead_id)
        return Response(SalesLeadSerializer(restored_lead).data)
